  domain <- hull$domain

  # Sample uniformly from domain and accept with envelope probability
  repeat {
    # Generate candidate point
    if (is.finite(domain[1]) && is.finite(domain[2])) {
      x_cand <- runif(1, domain[1], domain[2])
    } else if (is.finite(domain[1]) && !is.finite(domain[2])) {
      x_cand <- domain[1] + rexp(1, rate = 1)
    } else if (!is.finite(domain[1]) && is.finite(domain[2])) {
      x_cand <- domain[2] - rexp(1, rate = 1)
    } else {
      # Unbounded - use normal as proposal
      x_cand <- rnorm(1, mean = median(x_pts), sd = 2)
    }

    # Check bounds
    if (x_cand < domain[1] || x_cand > domain[2]) {
      next
    }

    # Compute upper envelope value
    upper_env <- evaluate_upper_envelope(x_cand, hull)

    if (!is.finite(upper_env)) {
      next
    }

    # Accept with probability based on envelope
    # Use log scale for numerical stability
    log_u <- log(runif(1))
    if (log_u <= upper_env - 20) {  # Normalize by subtracting constant
      return(x_cand)
    }
  }
}

