# Adaptive Rejection Sampling (ARS) Implementation
# Based on Gilks, W. R., & Wild, P. (1992)
# Adaptive rejection sampling for Gibbs sampling
# Journal of the Royal Statistical Society: Series C (Applied Statistics), 41(2), 337-348.

# ============================================================================
# Main ARS Function
# ============================================================================

ars <- function(n, logpdf, dlogpdf = NULL, x_init = NULL, domain = c(-Inf, Inf), ...) {
  # Input validation
  validate_ars_inputs(n, logpdf, dlogpdf, domain)

  # Initialize starting points if not provided
  if (is.null(x_init)) {
    x_init <- initialize_starting_points(domain)
  }

  # Initialize the hull (upper and lower envelopes)
  hull <- initialize_hull(x_init, logpdf, dlogpdf, domain, ...)

  # Sample n points
  samples <- numeric(n)
  n_accepted <- 0
  max_iterations <- n * 100  # safety limit
  iteration <- 0

  while (n_accepted < n && iteration < max_iterations) {
    iteration <- iteration + 1

    # Sample from upper envelope using mixture of exponentials
    x_candidate <- sample_from_envelope(hull)

    # Check if candidate is in domain
    if (x_candidate < hull$domain[1] || x_candidate > hull$domain[2]) {
      next
    }

    # Evaluate log-density at candidate
    logpdf_x <- logpdf(x_candidate, ...)

    # Get upper envelope value
    upper_envelope_x <- evaluate_upper_envelope(x_candidate, hull)

    # Generate uniform random variable
    u <- runif(1)

    # Accept/reject step
    if (log(u) <= logpdf_x - upper_envelope_x) {
      # Accept the sample
      n_accepted <- n_accepted + 1
      samples[n_accepted] <- x_candidate
    } else {
      # Reject but may update hull
      lower_envelope_x <- evaluate_lower_envelope(x_candidate, hull)

      if (log(u) <= lower_envelope_x - upper_envelope_x) {
        # Point is clearly rejected (below lower bound)
        # This indicates non-log-concavity
        stop("Non-log-concave density detected at x = ", round(x_candidate, 4),
             ". ARS requires log-concave densities.")
      } else {
        # Update hull with new point
        hull <- update_hull(x_candidate, logpdf, dlogpdf, hull, domain, ...)
      }
    }
  }

  if (n_accepted < n) {
    stop("Failed to generate ", n, " samples after ", max_iterations, " iterations")
  }

  return(samples)
}

# ============================================================================
# Input Validation Functions
# ============================================================================

validate_ars_inputs <- function(n, logpdf, dlogpdf, domain) {
  # Check n
  if (!is.numeric(n) || length(n) != 1) {
    stop("n must be a single numeric value")
  }
  if (n <= 0 || n != as.integer(n)) {
    stop("n must be a positive integer")
  }

  # Check logpdf
  if (!is.function(logpdf)) {
    stop("logpdf must be a function")
  }

  # Check dlogpdf
  if (!is.null(dlogpdf) && !is.function(dlogpdf)) {
    stop("dlogpdf must be a function or NULL")
  }

  # Check domain
  if (!is.numeric(domain) || length(domain) != 2) {
    stop("domain must be a numeric vector of length 2: c(lower, upper)")
  }
  if (domain[1] >= domain[2]) {
    stop("domain must satisfy lower < upper, got lower = ", domain[1],
         ", upper = ", domain[2])
  }

  invisible(NULL)
}

# ============================================================================
# Initialization Functions
# ============================================================================

initialize_starting_points <- function(domain) {
  # Choose initial points based on domain type
  if (is.finite(domain[1]) && is.finite(domain[2])) {
    # Bounded domain: use equally spaced points
    lower <- domain[1]
    upper <- domain[2]
    range <- upper - lower
    x_init <- c(lower + 0.25 * range, lower + 0.5 * range, lower + 0.75 * range)
  } else if (is.finite(domain[1]) && !is.finite(domain[2])) {
    # Left-bounded: space out from the boundary
    x_init <- c(domain[1] + 0.1, domain[1] + 1, domain[1] + 3)
  } else if (!is.finite(domain[1]) && is.finite(domain[2])) {
    # Right-bounded: space out from the boundary
    x_init <- c(domain[2] - 3, domain[2] - 1, domain[2] - 0.1)
  } else {
    # Unbounded: use symmetric points
    x_init <- c(-1, 0, 1)
  }

  return(sort(x_init))
}

initialize_hull <- function(x_init, logpdf, dlogpdf, domain, ...) {
  x_init <- sort(x_init)

  if (length(x_init) < 2) {
    stop("Need at least 2 initial points for the hull")
  }

  # Evaluate log-density at initial points
  fx <- numeric(length(x_init))
  for (i in seq_along(x_init)) {
    fx[i] <- logpdf(x_init[i], ...)
    if (!is.finite(fx[i])) {
      stop("logpdf returned non-finite value at x = ", x_init[i])
    }
  }

  # Compute derivatives
  dfx <- compute_derivatives(x_init, logpdf, dlogpdf, ...)

  # Verify log-concavity with initial points
  check_log_concavity_violation(x_init, fx, dfx)

  hull <- list(
    x = x_init,
    fx = fx,
    dfx = dfx,
    domain = domain
  )

  return(hull)
}

compute_derivatives <- function(x_points, logpdf, dlogpdf, ...) {
  dfx <- numeric(length(x_points))

  if (is.null(dlogpdf)) {
    # Use numerical differentiation
    h <- 1e-5
    for (i in seq_along(x_points)) {
      x <- x_points[i]
      h_val <- max(h, h * abs(x))  # Scale h with x magnitude
      f_plus <- logpdf(x + h_val, ...)
      f_minus <- logpdf(x - h_val, ...)
      dfx[i] <- (f_plus - f_minus) / (2 * h_val)
    }
  } else {
    # Use analytical derivative
    for (i in seq_along(x_points)) {
      dfx[i] <- dlogpdf(x_points[i], ...)
    }
  }

  if (any(!is.finite(dfx))) {
    stop("Derivative computation resulted in non-finite values")
  }

  return(dfx)
}

check_log_concavity_violation <- function(x_points, fx, dfx) {
  # For a log-concave function, the derivative should be non-increasing
  for (i in 1:(length(x_points) - 1)) {
    if (dfx[i] < dfx[i + 1] - 1e-6) {  # Allow small numerical tolerance
      warning("Density may not be log-concave: derivative at x = ",
              round(x_points[i], 4), " (", round(dfx[i], 4),
              ") is less than at x = ", round(x_points[i + 1], 4),
              " (", round(dfx[i + 1], 4), ")")
    }
  }
}

# ============================================================================
# Envelope Functions
# ============================================================================

evaluate_upper_envelope <- function(x, hull) {
  x_pts <- hull$x
  fx <- hull$fx
  dfx <- hull$dfx
  domain <- hull$domain

  # Ensure x is in valid range
  if (x < domain[1] || x > domain[2]) {
    return(NA)
  }

  # For points beyond the hull, use extrapolation with outermost tangent
  if (x <= x_pts[1]) {
    return(fx[1] + dfx[1] * (x - x_pts[1]))
  }
  if (x >= x_pts[length(x_pts)]) {
    return(fx[length(x_pts)] + dfx[length(x_pts)] * (x - x_pts[length(x_pts)]))
  }

  # Find the interval containing x
  idx <- findInterval(x, x_pts)
  x_left <- x_pts[idx]
  x_right <- x_pts[idx + 1]
  f_left <- fx[idx]
  f_right <- fx[idx + 1]
  df_left <- dfx[idx]
  df_right <- dfx[idx + 1]

  # Compute intersection point of the two tangent lines
  if (abs(df_left - df_right) < 1e-10) {
    # Parallel lines - use left tangent
    tangent_left <- f_left + df_left * (x - x_left)
    return(tangent_left)
  } else {
    x_intersect <- (f_right - f_left - df_right * x_right + df_left * x_left) /
                   (df_left - df_right)

    if (x <= x_intersect) {
      # Use left tangent
      return(f_left + df_left * (x - x_left))
    } else {
      # Use right tangent
      return(f_right + df_right * (x - x_right))
    }
  }
}

evaluate_lower_envelope <- function(x, hull) {
  x_pts <- hull$x
  fx <- hull$fx
  domain <- hull$domain

  # Lower envelope is only defined within the original hull
  if (x <= x_pts[1] || x >= x_pts[length(x_pts)]) {
    return(-Inf)
  }

  # Find the interval containing x
  idx <- findInterval(x, x_pts)
  x_left <- x_pts[idx]
  x_right <- x_pts[idx + 1]
  f_left <- fx[idx]
  f_right <- fx[idx + 1]

  # Linear interpolation between consecutive points
  lower_val <- f_left + (f_right - f_left) * (x - x_left) / (x_right - x_left)

  return(lower_val)
}

update_hull <- function(x_new, logpdf, dlogpdf, hull, domain, ...) {
  # Find where to insert the new point
  insert_pos <- sum(hull$x < x_new) + 1

  # Evaluate at new point
  fx_new <- logpdf(x_new, ...)
  if (!is.finite(fx_new)) {
    stop("logpdf returned non-finite value at x = ", x_new)
  }

  # Compute derivative at new point
  dfx_new <- if (is.null(dlogpdf)) {
    h <- 1e-5
    h_val <- max(h, h * abs(x_new))
    (logpdf(x_new + h_val, ...) - logpdf(x_new - h_val, ...)) / (2 * h_val)
  } else {
    dlogpdf(x_new, ...)
  }

  if (!is.finite(dfx_new)) {
    stop("Derivative computation resulted in non-finite value at x = ", x_new)
  }

  # Insert new point
  x_updated <- insert(hull$x, insert_pos, x_new)
  fx_updated <- insert(hull$fx, insert_pos, fx_new)
  dfx_updated <- insert(hull$dfx, insert_pos, dfx_new)

  # Check for log-concavity violation
  if (insert_pos > 1 && insert_pos < length(x_updated)) {
    check_log_concavity_violation(x_updated, fx_updated, dfx_updated)
  }

  hull <- list(
    x = x_updated,
    fx = fx_updated,
    dfx = dfx_updated,
    domain = domain
  )

  return(hull)
}

# Helper function to insert element into vector at position
insert <- function(x, pos, value) {
  c(x[1:(pos - 1)], value, x[pos:length(x)])
}

# ============================================================================
# Sampling from Envelope
# ============================================================================

sample_from_envelope <- function(hull) {
  x_pts <- hull$x
  fx <- hull$fx
  dfx <- hull$dfx
  domain <- hull$domain

  # Create piecewise exponential distribution for the upper envelope
  # For each segment, compute the normalization constant

  n_segments <- length(x_pts) - 1
  segment_weights <- numeric(n_segments)

  for (i in 1:n_segments) {
    x_left <- x_pts[i]
    x_right <- x_pts[i + 1]
    f_left <- fx[i]
    df_left <- dfx[i]
    f_right <- fx[i + 1]
    df_right <- dfx[i + 1]

    # Compute intersection of tangent lines
    if (abs(df_left - df_right) < 1e-10) {
      # Parallel lines
      x_int <- (x_left + x_right) / 2
    } else {
      x_int <- (f_right - f_left - df_right * x_right + df_left * x_left) /
               (df_left - df_right)
    }

    # Clamp intersection to segment boundaries
    x_int <- pmax(x_left, pmin(x_int, x_right))

    # Compute segment weight (exponential rate)
    weight <- compute_segment_weight(x_left, x_right, x_int, f_left, f_right,
                                     df_left, df_right)
    segment_weights[i] <- pmax(weight, 1e-10)  # Ensure positive
  }

  # Normalize weights
  segment_weights <- segment_weights / sum(segment_weights)

  # Sample a segment
  segment <- sample(1:n_segments, size = 1, prob = segment_weights)

  # Sample from the selected segment
  x_sampled <- sample_segment(segment, x_pts, fx, dfx)

  return(x_sampled)
}

compute_segment_weight <- function(x_left, x_right, x_int, f_left, f_right,
                                   df_left, df_right) {
  # Approximate weight of the segment under the envelope
  # Using the area under the piecewise linear upper envelope

  if (x_int < x_left || x_int > x_right) {
    x_int <- (x_left + x_right) / 2
  }

  # Weight is roughly proportional to the range and the exponential values
  range <- x_right - x_left
  max_val <- max(f_left + df_left * (x_int - x_left),
                 f_right + df_right * (x_int - x_right))

  weight <- range * exp(max_val - 20)  # Subtract constant for numerical stability

  return(weight)
}

sample_segment <- function(segment_idx, x_pts, fx, dfx) {
  x_left <- x_pts[segment_idx]
  x_right <- x_pts[segment_idx + 1]
  f_left <- fx[segment_idx]
  df_left <- dfx[segment_idx]
  f_right <- fx[segment_idx + 1]
  df_right <- dfx[segment_idx + 1]

  # For a piecewise linear envelope, sample using inverse transform
  repeat {
    u <- runif(1)

    # Attempt rejection sampling within segment
    x_cand <- x_left + u * (x_right - x_left)

    # Evaluate upper envelope at candidate
    if (abs(df_left - df_right) < 1e-10) {
      upper_val <- f_left + df_left * (x_cand - x_left)
    } else {
      x_int <- (f_right - f_left - df_right * x_right + df_left * x_left) /
               (df_left - df_right)
      x_int <- pmax(x_left, pmin(x_int, x_right))

      if (x_cand <= x_int) {
        upper_val <- f_left + df_left * (x_cand - x_left)
      } else {
        upper_val <- f_right + df_right * (x_cand - x_right)
      }
    }

    # Accept with probability proportional to envelope value
    if (log(runif(1)) <= upper_val - 20) {  # Numerically stable
      return(x_cand)
    }
  }
}

# ============================================================================
# Test Function
# ============================================================================

test <- function() {
  cat("=============================================================\n")
  cat("Adaptive Rejection Sampling - Formal Testing\n")
  cat("=============================================================\n\n")

  # Set random seed for reproducibility
  set.seed(12345)

  # Test parameters
  n_samples <- 5000
  results <- list()

  # -----------------------------------------------------------------------
  # Test 1: Standard Normal Distribution
  # -----------------------------------------------------------------------
  cat("TEST 1: Standard Normal Distribution\n")
  cat("----------------------------------------\n")

  logpdf_normal <- function(x) {
    -0.5 * x^2 - 0.5 * log(2 * pi)
  }

  dlogpdf_normal <- function(x) {
    -x
  }

  tryCatch({
    samples_normal <- ars(n_samples, logpdf_normal, dlogpdf_normal,
                         x_init = c(-2, 0, 2), domain = c(-10, 10))

    mean_normal <- mean(samples_normal)
    sd_normal <- sd(samples_normal)

    cat("  Mean:", format(round(mean_normal, 4), width = 8),
        "(expected: 0.0000)\n")
    cat("  SD:  ", format(round(sd_normal, 4), width = 8),
        "(expected: 1.0000)\n")

    # Check if results are reasonable
    mean_check <- abs(mean_normal) < 0.15
    sd_check <- abs(sd_normal - 1) < 0.15

    if (mean_check && sd_check) {
      cat("  TEST 1: PASS\n\n")
      results$test1 <- TRUE
    } else {
      cat("  TEST 1: FAIL\n")
      cat("    Mean check:", mean_check, "| SD check:", sd_check, "\n\n")
      results$test1 <- FALSE
    }

    # Save samples
    write.table(samples_normal, "/app/normal_samples.txt",
               row.names = FALSE, col.names = FALSE)
    cat("  Samples saved to: /app/normal_samples.txt\n\n")

  }, error = function(e) {
    cat("  TEST 1: FAIL\n")
    cat("  Error:", conditionMessage(e), "\n\n")
    results$test1 <<- FALSE
  })

  # -----------------------------------------------------------------------
  # Test 2: Exponential Distribution
  # -----------------------------------------------------------------------
  cat("TEST 2: Exponential Distribution (rate = 1)\n")
  cat("----------------------------------------\n")

  logpdf_exp <- function(x) {
    if (any(x < 0)) {
      return(rep(-Inf, length(x)))
    }
    -x
  }

  dlogpdf_exp <- function(x) {
    -1
  }

  tryCatch({
    samples_exp <- ars(n_samples, logpdf_exp, dlogpdf_exp,
                       x_init = c(0.2, 0.8, 2), domain = c(0, Inf))

    mean_exp <- mean(samples_exp)
    sd_exp <- sd(samples_exp)

    cat("  Mean:", format(round(mean_exp, 4), width = 8),
        "(expected: 1.0000)\n")
    cat("  SD:  ", format(round(sd_exp, 4), width = 8),
        "(expected: 1.0000)\n")

    # Check if results are reasonable
    mean_check <- abs(mean_exp - 1) < 0.25
    sd_check <- abs(sd_exp - 1) < 0.25

    if (mean_check && sd_check) {
      cat("  TEST 2: PASS\n\n")
      results$test2 <- TRUE
    } else {
      cat("  TEST 2: FAIL\n")
      cat("    Mean check:", mean_check, "| SD check:", sd_check, "\n\n")
      results$test2 <- FALSE
    }

    # Save samples
    write.table(samples_exp, "/app/exponential_samples.txt",
               row.names = FALSE, col.names = FALSE)
    cat("  Samples saved to: /app/exponential_samples.txt\n\n")

  }, error = function(e) {
    cat("  TEST 2: FAIL\n")
    cat("  Error:", conditionMessage(e), "\n\n")
    results$test2 <<- FALSE
  })

  # -----------------------------------------------------------------------
  # Test 3: Beta Distribution (log-concave)
  # -----------------------------------------------------------------------
  cat("TEST 3: Beta Distribution (alpha = 5, beta = 3)\n")
  cat("----------------------------------------\n")

  alpha <- 5
  beta <- 3

  logpdf_beta <- function(x) {
    if (x <= 0 || x >= 1) return(-Inf)
    (alpha - 1) * log(x) + (beta - 1) * log(1 - x) +
      lgamma(alpha + beta) - lgamma(alpha) - lgamma(beta)
  }

  dlogpdf_beta <- function(x) {
    (alpha - 1) / x - (beta - 1) / (1 - x)
  }

  tryCatch({
    samples_beta <- ars(n_samples, logpdf_beta, dlogpdf_beta,
                       x_init = c(0.3, 0.5, 0.7), domain = c(0, 1))

    mean_beta <- mean(samples_beta)
    expected_mean_beta <- alpha / (alpha + beta)
    sd_beta <- sd(samples_beta)
    expected_sd_beta <- sqrt((alpha * beta) / ((alpha + beta)^2 * (alpha + beta + 1)))

    cat("  Mean:", format(round(mean_beta, 4), width = 8),
        "(expected:", format(round(expected_mean_beta, 4), width = 8), ")\n")
    cat("  SD:  ", format(round(sd_beta, 4), width = 8),
        "(expected:", format(round(expected_sd_beta, 4), width = 8), ")\n")

    # Check if results are reasonable
    mean_check <- abs(mean_beta - expected_mean_beta) < 0.1
    sd_check <- abs(sd_beta - expected_sd_beta) < 0.1

    if (mean_check && sd_check) {
      cat("  TEST 3: PASS\n\n")
      results$test3 <- TRUE
    } else {
      cat("  TEST 3: FAIL\n")
      cat("    Mean check:", mean_check, "| SD check:", sd_check, "\n\n")
      results$test3 <- FALSE
    }

  }, error = function(e) {
    cat("  TEST 3: FAIL\n")
    cat("  Error:", conditionMessage(e), "\n\n")
    results$test3 <<- FALSE
  })

  # -----------------------------------------------------------------------
  # Test 4: Input Validation
  # -----------------------------------------------------------------------
  cat("TEST 4: Input Validation\n")
  cat("----------------------------------------\n")

  validation_pass <- TRUE

  # Test 4a: Invalid n
  tryCatch({
    ars(-5, logpdf_normal)
    cat("  4a. Negative n: FAIL (should have thrown error)\n")
    validation_pass <- FALSE
  }, error = function(e) {
    if (grepl("positive integer", conditionMessage(e))) {
      cat("  4a. Negative n: PASS (correctly rejected)\n")
    } else {
      cat("  4a. Negative n: FAIL (wrong error)\n")
      validation_pass <<- FALSE
    }
  })

  # Test 4b: Non-function logpdf
  tryCatch({
    ars(100, "not a function")
    cat("  4b. Non-function logpdf: FAIL (should have thrown error)\n")
    validation_pass <- FALSE
  }, error = function(e) {
    if (grepl("must be a function", conditionMessage(e))) {
      cat("  4b. Non-function logpdf: PASS (correctly rejected)\n")
    } else {
      cat("  4b. Non-function logpdf: FAIL (wrong error)\n")
      validation_pass <<- FALSE
    }
  })

  # Test 4c: Invalid domain
  tryCatch({
    ars(100, logpdf_normal, domain = c(5, 2))
    cat("  4c. Invalid domain (lower >= upper): FAIL (should have thrown error)\n")
    validation_pass <- FALSE
  }, error = function(e) {
    if (grepl("lower < upper", conditionMessage(e))) {
      cat("  4c. Invalid domain (lower >= upper): PASS (correctly rejected)\n")
    } else {
      cat("  4c. Invalid domain (lower >= upper): FAIL (wrong error)\n")
      validation_pass <<- FALSE
    }
  })

  if (validation_pass) {
    cat("  TEST 4: PASS\n\n")
    results$test4 <- TRUE
  } else {
    cat("  TEST 4: FAIL\n\n")
    results$test4 <- FALSE
  }

  # -----------------------------------------------------------------------
  # Summary
  # -----------------------------------------------------------------------
  cat("=============================================================\n")
  cat("SUMMARY\n")
  cat("=============================================================\n")

  n_tests <- length(results)
  n_passed <- sum(unlist(results))

  for (i in seq_along(results)) {
    test_name <- paste0("TEST ", i)
    status <- if (results[[i]]) "PASS" else "FAIL"
    cat(sprintf("%-10s: %s\n", test_name, status))
  }

  cat("\n")
  cat(sprintf("Tests Passed: %d/%d\n", n_passed, n_tests))

  if (n_passed == n_tests) {
    cat("\n*** ALL TESTS PASSED ***\n")
  } else {
    cat("\n*** SOME TESTS FAILED ***\n")
  }
  cat("\n")

  invisible(results)
}

