tool_use_result.content:
# Adaptive Rejection Sampling (ARS) Implementation
# Based on Gilks, W. R., & Wild, P. (1992)
# Adaptive rejection sampling for Gibbs sampling
# Journal of the Royal Statistical Society: Series C (Applied Statistics), 41(2), 337-348.

# ============================================================================
# Main ARS Function
# ============================================================================

ars <- function(n, logpdf, dlogpdf = NULL, x_init = NULL, domain = c(-Inf, Inf), ...) {
  # Input validation
  validate_ars_inputs(n, logpdf, dlogpdf, domain)

  # Initialize starting points if not provided
  if (is.null(x_init)) {
    x_init <- initialize_starting_points(domain)
  }

  # Initialize the hull (upper and lower envelopes)
  hull <- initialize_hull(x_init, logpdf, dlogpdf, domain, ...)

  # Sample n points
  samples <- numeric(n)
  n_accepted <- 0
  max_iterations <- n * 50
  iteration <- 0

  while (n_accepted < n && iteration < max_iterations) {
    iteration <- iteration + 1

    # Sample from upper envelope
    x_candidate <- sample_from_envelope(hull)

    # Evaluate log-density at candidate
    logpdf_x <- tryCatch(
      logpdf(x_candidate, ...),
      error = function(e) -Inf
    )

    if (!is.finite(logpdf_x)) {
      next
    }

    # Get upper envelope value
    upper_envelope_x <- evaluate_upper_envelope(x_candidate, hull)

    if (!is.finite(upper_envelope_x) || upper_envelope_x < logpdf_x - 1e-6) {
      stop("Upper envelope violated at x = ", round(x_candidate, 4),
           ": logpdf = ", round(logpdf_x, 4),
           ", envelope = ", round(upper_envelope_x, 4))
    }

    # Generate uniform random variable
    u <- runif(1)

    # Accept/reject using log scale
    log_ratio <- logpdf_x - upper_envelope_x

    if (log(u) <= log_ratio) {
      # Accept
      n_accepted <- n_accepted + 1
      samples[n_accepted] <- x_candidate
    } else {
      # Check lower envelope for log-concavity violation
      lower_envelope_x <- evaluate_lower_envelope(x_candidate, hull)

      if (logpdf_x < lower_envelope_x - 1e-6) {
        stop("Log-concavity violated: density < lower envelope at x = ",
             round(x_candidate, 4))
      }

      # Update hull with new point for better envelope
      if (length(hull$x) < 20) {  # Limit hull size
        hull <- update_hull(x_candidate, logpdf, dlogpdf, hull, domain, ...)
      }
    }
  }

  if (n_accepted < n) {
    stop("Failed to generate ", n, " samples after ", max_iterations, " iterations")
  }

  return(samples[1:n])
}

# ============================================================================
# Input Validation
# ============================================================================

validate_ars_inputs <- function(n, logpdf, dlogpdf, domain) {
  if (!is.numeric(n) || length(n) != 1) {
    stop("n must be a single numeric value")
  }
  if (n <= 0 || n != as.integer(n)) {
    stop("n must be a positive integer")
  }

  if (!is.function(logpdf)) {
    stop("logpdf must be a function")
  }

  if (!is.null(dlogpdf) && !is.function(dlogpdf)) {
    stop("dlogpdf must be a function or NULL")
  }

  if (!is.numeric(domain) || length(domain) != 2) {
    stop("domain must be a numeric vector of length 2: c(lower, upper)")
  }
  if (domain[1] >= domain[2]) {
    stop("domain must satisfy lower < upper, got lower = ", domain[1],
         ", upper = ", domain[2])
  }

  invisible(NULL)
}

# ============================================================================
# Initialization
# ============================================================================

initialize_starting_points <- function(domain) {
  if (is.finite(domain[1]) && is.finite(domain[2])) {
    lower <- domain[1]
    upper <- domain[2]
    range <- upper - lower
    x_init <- c(lower + 0.25 * range, lower + 0.5 * range, lower + 0.75 * range)
  } else if (is.finite(domain[1]) && !is.finite(domain[2])) {
    x_init <- c(domain[1] + 0.1, domain[1] + 1, domain[1] + 3)
  } else if (!is.finite(domain[1]) && is.finite(domain[2])) {
    x_init <- c(domain[2] - 3, domain[2] - 1, domain[2] - 0.1)
  } else {
    x_init <- c(-1, 0, 1)
  }

  return(sort(x_init))
}

initialize_hull <- function(x_init, logpdf, dlogpdf, domain, ...) {
  x_init <- sort(unique(x_init))

  if (length(x_init) < 2) {
    stop("Need at least 2 initial points for the hull")
  }

  # Evaluate log-density
  fx <- numeric(length(x_init))
  for (i in seq_along(x_init)) {
    fx[i] <- tryCatch(
      logpdf(x_init[i], ...),
      error = function(e) -Inf
    )
    if (!is.finite(fx[i])) {
      stop("logpdf returned non-finite value at x = ", x_init[i])
    }
  }

  # Compute derivatives
  dfx <- compute_derivatives(x_init, logpdf, dlogpdf, ...)

  hull <- list(
    x = x_init,
    fx = fx,
    dfx = dfx,
    domain = domain
  )

  return(hull)
}

compute_derivatives <- function(x_points, logpdf, dlogpdf, ...) {
  dfx <- numeric(length(x_points))

  if (is.null(dlogpdf)) {
    # Numerical differentiation
    h <- 1e-5
    for (i in seq_along(x_points)) {
      x <- x_points[i]
      h_val <- max(h, h * abs(x))
      f_plus <- tryCatch(logpdf(x + h_val, ...), error = function(e) -Inf)
      f_minus <- tryCatch(logpdf(x - h_val, ...), error = function(e) -Inf)
      if (is.finite(f_plus) && is.finite(f_minus)) {
        dfx[i] <- (f_plus - f_minus) / (2 * h_val)
      } else {
        dfx[i] <- 0
      }
    }
  } else {
    # Analytical derivative
    for (i in seq_along(x_points)) {
      dfx[i] <- tryCatch(
        dlogpdf(x_points[i], ...),
        error = function(e) 0
      )
    }
  }

  return(dfx)
}

# ============================================================================
# Envelope Evaluation
# ============================================================================

evaluate_upper_envelope <- function(x, hull) {
  x_pts <- hull$x
  fx <- hull$fx
  dfx <- hull$dfx
  domain <- hull$domain

  # Check bounds
  if (x < domain[1] || x > domain[2]) {
    return(NA)
  }

  # Outside hull: use extrapolation
  if (x <= x_pts[1]) {
    return(fx[1] + dfx[1] * (x - x_pts[1]))
  }
  if (x >= x_pts[length(x_pts)]) {
    return(fx[length(x_pts)] + dfx[length(x_pts)] * (x - x_pts[length(x_pts)]))
  }

  # Find interval
  idx <- findInterval(x, x_pts)
  x_left <- x_pts[idx]
  x_right <- x_pts[idx + 1]
  f_left <- fx[idx]
  f_right <- fx[idx + 1]
  df_left <- dfx[idx]
  df_right <- dfx[idx + 1]

  # Compute tangent line values
  tangent_left <- f_left + df_left * (x - x_left)
  tangent_right <- f_right + df_right * (x - x_right)

  # Upper envelope is the minimum of the two tangents (for log-concave)
  return(min(tangent_left, tangent_right))
}

evaluate_lower_envelope <- function(x, hull) {
  x_pts <- hull$x
  fx <- hull$fx
  domain <- hull$domain

  # Lower envelope only defined within original hull
  if (x <= x_pts[1] || x >= x_pts[length(x_pts)]) {
    return(-Inf)
  }

  idx <- findInterval(x, x_pts)
  x_left <- x_pts[idx]
  x_right <- x_pts[idx + 1]
  f_left <- fx[idx]
  f_right <- fx[idx + 1]

  # Linear interpolation
  lower_val <- f_left + (f_right - f_left) * (x - x_left) / (x_right - x_left)

  return(lower_val)
}

update_hull <- function(x_new, logpdf, dlogpdf, hull, domain, ...) {
  # Insert x_new in sorted order
  insert_pos <- sum(hull$x < x_new) + 1

  # Evaluate at new point
  fx_new <- tryCatch(
    logpdf(x_new, ...),
    error = function(e) -Inf
  )

  if (!is.finite(fx_new)) {
    return(hull)
  }

  # Compute derivative
  dfx_new <- if (is.null(dlogpdf)) {
    h <- 1e-5
    h_val <- max(h, h * abs(x_new))
    f_plus <- tryCatch(logpdf(x_new + h_val, ...), error = function(e) -Inf)
    f_minus <- tryCatch(logpdf(x_new - h_val, ...), error = function(e) -Inf)
    if (is.finite(f_plus) && is.finite(f_minus)) {
      (f_plus - f_minus) / (2 * h_val)
    } else {
      0
    }
  } else {
    tryCatch(dlogpdf(x_new, ...), error = function(e) 0)
  }

  # Insert
  x_updated <- c(hull$x[1:(insert_pos - 1)], x_new,
                 if (insert_pos <= length(hull$x)) hull$x[insert_pos:length(hull$x)] else numeric(0))
  fx_updated <- c(hull$fx[1:(insert_pos - 1)], fx_new,
                  if (insert_pos <= length(hull$fx)) hull$fx[insert_pos:length(hull$fx)] else numeric(0))
  dfx_updated <- c(hull$dfx[1:(insert_pos - 1)], dfx_new,
                   if (insert_pos <= length(hull$dfx)) hull$dfx[insert_pos:length(hull$dfx)] else numeric(0))

  hull <- list(
    x = x_updated,
    fx = fx_updated,
    dfx = dfx_updated,
    domain = domain
  )

  return(hull)
}

# ============================================================================
# Sampling from Envelope
# ============================================================================

sample_from_envelope <- function(hull) {
  x_pts <- hull$x
  fx <- hull$fx
  dfx <- hull$dfx
  domain <- hull$domain

  repeat {
    # Propose from uniform on domain
    if (is.finite(domain[1]) && is.finite(domain[2])) {
      x_prop <- runif(1, domain[1], domain[2])
    } else if (is.finite(domain[1])) {
      x_prop <- domain[1] + rexp(1, rate = 0.5)
    } else if (is.finite(domain[2])) {
      x_prop <- domain[2] - rexp(1, rate = 0.5)
    } else {
      x_prop <- rnorm(1, mean = 0, sd = 2)
    }

    # Check bounds
    if (x_prop < domain[1] || x_prop > domain[2]) {
      next
    }

    # Evaluate upper envelope
    upper_env <- evaluate_upper_envelope(x_prop, hull)

    if (!is.finite(upper_env)) {
      next
    }

    # Find reference point for normalization
    max_env <- max(fx)  # Maximum value of f at hull points

    # Rejection sampling
    log_u <- log(runif(1))
    if (log_u <= upper_env - max_env) {
      return(x_prop)
    }
  }
}

# ============================================================================
# Test Function
# ============================================================================

test <- function() {
  cat("=============================================================\n")
  cat("Adaptive Rejection Sampling - Formal Testing\n")
  cat("=============================================================\n\n")

  set.seed(12345)

  n_samples <- 2000
  results <- list()

  # -----------------------------------------------------------------------
  # Test 1: Standard Normal Distribution
  # -----------------------------------------------------------------------
  cat("TEST 1: Standard Normal Distribution\n")
  cat("----------------------------------------\n")

  logpdf_normal <- function(x) {
    -0.5 * x^2 - 0.5 * log(2 * pi)
  }

  dlogpdf_normal <- function(x) {
    -x
  }

  tryCatch({
    cat("  Sampling 2000 points...\n")
    samples_normal <- ars(n_samples, logpdf_normal, dlogpdf_normal,
                         x_init = c(-2, 0, 2), domain = c(-8, 8))

    mean_normal <- mean(samples_normal)
    sd_normal <- sd(samples_normal)

    cat("  Mean:", format(round(mean_normal, 4), width = 8),
        "(expected: 0.0000)\n")
    cat("  SD:  ", format(round(sd_normal, 4), width = 8),
        "(expected: 1.0000)\n")

    mean_check <- abs(mean_normal) < 0.15
    sd_check <- abs(sd_normal - 1) < 0.15

    if (mean_check && sd_check) {
      cat("  TEST 1: PASS\n\n")
      results$test1 <- TRUE
    } else {
      cat("  TEST 1: FAIL\n\n")
      results$test1 <- FALSE
    }

    write.table(samples_normal, "/app/normal_samples.txt",
               row.names = FALSE, col.names = FALSE)

  }, error = function(e) {
    cat("  TEST 1: FAIL\n  Error:", conditionMessage(e), "\n\n")
    results$test1 <<- FALSE
  })

  # -----------------------------------------------------------------------
  # Test 2: Exponential Distribution
  # -----------------------------------------------------------------------
  cat("TEST 2: Exponential Distribution (rate = 1)\n")
  cat("----------------------------------------\n")

  logpdf_exp <- function(x) {
    if (x < 0) return(-Inf)
    -x
  }

  dlogpdf_exp <- function(x) {
    -1
  }

  tryCatch({
    cat("  Sampling 2000 points...\n")
    samples_exp <- ars(n_samples, logpdf_exp, dlogpdf_exp,
                       x_init = c(0.2, 0.8, 2), domain = c(0, 20))

    mean_exp <- mean(samples_exp)
    sd_exp <- sd(samples_exp)

    cat("  Mean:", format(round(mean_exp, 4), width = 8),
        "(expected: 1.0000)\n")
    cat("  SD:  ", format(round(sd_exp, 4), width = 8),
        "(expected: 1.0000)\n")

    mean_check <- abs(mean_exp - 1) < 0.3
    sd_check <- abs(sd_exp - 1) < 0.3

    if (mean_check && sd_check) {
      cat("  TEST 2: PASS\n\n")
      results$test2 <- TRUE
    } else {
      cat("  TEST 2: FAIL\n\n")
      results$test2 <- FALSE
    }

    write.table(samples_exp, "/app/exponential_samples.txt",
               row.names = FALSE, col.names = FALSE)

  }, error = function(e) {
    cat("  TEST 2: FAIL\n  Error:", conditionMessage(e), "\n\n")
    results$test2 <<- FALSE
  })

  # -----------------------------------------------------------------------
  # Test 3: Beta Distribution
  # -----------------------------------------------------------------------
  cat("TEST 3: Beta Distribution (alpha = 5, beta = 3)\n")
  cat("----------------------------------------\n")

  alpha <- 5
  beta <- 3

  logpdf_beta <- function(x) {
    if (x <= 0 || x >= 1) return(-Inf)
    (alpha - 1) * log(x) + (beta - 1) * log(1 - x) +
      lgamma(alpha + beta) - lgamma(alpha) - lgamma(beta)
  }

  dlogpdf_beta <- function(x) {
    (alpha - 1) / x - (beta - 1) / (1 - x)
  }

  tryCatch({
    cat("  Sampling 2000 points...\n")
    samples_beta <- ars(n_samples, logpdf_beta, dlogpdf_beta,
                       x_init = c(0.3, 0.5, 0.7), domain = c(0.001, 0.999))

    mean_beta <- mean(samples_beta)
    expected_mean_beta <- alpha / (alpha + beta)
    sd_beta <- sd(samples_beta)
    expected_sd_beta <- sqrt((alpha * beta) /
                             ((alpha + beta)^2 * (alpha + beta + 1)))

    cat("  Mean:", format(round(mean_beta, 4), width = 8),
        "(expected:", format(round(expected_mean_beta, 4), width = 8), ")\n")
    cat("  SD:  ", format(round(sd_beta, 4), width = 8),
        "(expected:", format(round(expected_sd_beta, 4), width = 8), ")\n")

    mean_check <- abs(mean_beta - expected_mean_beta) < 0.12
    sd_check <- abs(sd_beta - expected_sd_beta) < 0.12

    if (mean_check && sd_check) {
      cat("  TEST 3: PASS\n\n")
      results$test3 <- TRUE
    } else {
      cat("  TEST 3: FAIL\n\n")
      results$test3 <- FALSE
    }

  }, error = function(e) {
    cat("  TEST 3: FAIL\n  Error:", conditionMessage(e), "\n\n")
    results$test3 <<- FALSE
  })

  # -----------------------------------------------------------------------
  # Test 4: Input Validation
  # -----------------------------------------------------------------------
  cat("TEST 4: Input Validation\n")
  cat("----------------------------------------\n")

  validation_pass <- TRUE

  tryCatch({
    ars(-5, logpdf_normal)
    cat("  4a. Negative n: FAIL (should have thrown error)\n")
    validation_pass <- FALSE
  }, error = function(e) {
    if (grepl("positive integer", conditionMessage(e))) {
      cat("  4a. Negative n: PASS (correctly rejected)\n")
    } else {
      cat("  4a. Negative n: FAIL (wrong error)\n")
      validation_pass <<- FALSE
    }
  })

  tryCatch({
    ars(100, "not a function")
    cat("  4b. Non-function logpdf: FAIL (should have thrown error)\n")
    validation_pass <- FALSE
  }, error = function(e) {
    if (grepl("must be a function", conditionMessage(e))) {
      cat("  4b. Non-function logpdf: PASS (correctly rejected)\n")
    } else {
      cat("  4b. Non-function logpdf: FAIL (wrong error)\n")
      validation_pass <<- FALSE
    }
  })

  tryCatch({
    ars(100, logpdf_normal, domain = c(5, 2))
    cat("  4c. Invalid domain: FAIL (should have thrown error)\n")
    validation_pass <- FALSE
  }, error = function(e) {
    if (grepl("lower < upper", conditionMessage(e))) {
      cat("  4c. Invalid domain: PASS (correctly rejected)\n")
    } else {
      cat("  4c. Invalid domain: FAIL (wrong error)\n")
      validation_pass <<- FALSE
    }
  })

  if (validation_pass) {
    cat("  TEST 4: PASS\n\n")
    results$test4 <- TRUE
  } else {
    cat("  TEST 4: FAIL\n\n")
    results$test4 <- FALSE
  }

  # -----------------------------------------------------------------------
  # Summary
  # -----------------------------------------------------------------------
  cat("=============================================================\n")
  cat("SUMMARY\n")
  cat("=============================================================\n")

  n_tests <- length(results)
  n_passed <- sum(unlist(results))

  for (i in seq_along(results)) {
    test_name <- paste0("TEST ", i)
    status <- if (results[[i]]) "PASS" else "FAIL"
    cat(sprintf("%-10s: %s\n", test_name, status))
  }

  cat("\nTests Passed: ", n_passed, "/", n_tests, "\n", sep = "")

  if (n_passed == n_tests) {
    cat("\n*** ALL TESTS PASSED ***\n")
  } else {
    cat("\n*** SOME TESTS FAILED ***\n")
  }
  cat("\n")

  invisible(results)
}

