update_hull <- function(x_new, logpdf, dlogpdf, hull, domain, ...) {
  # Check if x_new is already in hull
  if (any(abs(hull$x - x_new) < 1e-8)) {
    return(hull)
  }

  # Evaluate at new point
  fx_new <- tryCatch(
    logpdf(x_new, ...),
    error = function(e) -Inf
  )

  if (!is.finite(fx_new)) {
    return(hull)
  }

  # Compute derivative
  dfx_new <- if (is.null(dlogpdf)) {
    h <- 1e-5
    h_val <- max(h, h * abs(x_new))
    f_plus <- tryCatch(logpdf(x_new + h_val, ...), error = function(e) -Inf)
    f_minus <- tryCatch(logpdf(x_new - h_val, ...), error = function(e) -Inf)
    if (is.finite(f_plus) && is.finite(f_minus)) {
      (f_plus - f_minus) / (2 * h_val)
    } else {
      0
    }
  } else {
    tryCatch(dlogpdf(x_new, ...), error = function(e) 0)
  }

  # Add point and re-sort
  x_all <- c(hull$x, x_new)
  fx_all <- c(hull$fx, fx_new)
  dfx_all <- c(hull$dfx, dfx_new)

  sort_idx <- order(x_all)

  hull <- list(
    x = x_all[sort_idx],
    fx = fx_all[sort_idx],
    dfx = dfx_all[sort_idx],
    domain = domain
  )

  return(hull)
}

